import{_ as e,a as i,b as o,c as s,d as a,e as n,f as r,g as c}from"./chunks/en_m_nastaveni.CupdCm4p.js";import{_ as l}from"./chunks/m_btn_hamburger.CftTsS04.js";import{_ as h,o as p,c as g,aa as d}from"./chunks/framework.BAs_AphD.js";const T=JSON.parse('{"title":"Main App Menu","description":"","frontmatter":{"title":"Main App Menu","wiki":"en:tickets:m_project_list"},"headers":[],"relativePath":"en/tickets/m_project_list.md","filePath":"en/tickets/m_project_list.md","lastUpdated":1794388980000}'),u={name:"en/tickets/m_project_list.md"};function m(f,t,y,w,_,b){return p(),g("div",null,[...t[0]||(t[0]=[d('<h1 id="main-app-menu" tabindex="-1">Main App Menu <a class="header-anchor" href="#main-app-menu" aria-label="Permalink to &quot;Main App Menu&quot;">​</a></h1><figure class="shot" style="--w:280px;"><img src="'+e+'" alt="App Navigation Menu" width="250" loading="lazy"></figure><p>The app navigation menu is accessible from almost anywhere using the hamburger menu <img src="'+l+'" alt="Hamburger Menu - App Navigation Menu" width="20" data-no-zoom loading="lazy"> in the top-left corner. If a left-pointing arrow ← is displayed here, follow it first, and the required icon will then appear.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>The Main Menu is very similar to the navigation panel in the web version of the app, so navigating through it should be simple and intuitive for users.</p><p>It is only necessary to keep in mind that the functionality of the Mobile App is limited, particularly when it comes to configuration options.</p></div><p>In the upper third of the menu, against the background of a project image, the <strong>short project name</strong> and the name of its <strong>last viewed diary</strong> are displayed.</p><p>Below this information is the <strong>name of the logged-in account (email address)</strong>.</p><p>The active <strong>Project List</strong> and <strong>Settings</strong> icons link to the respective pages, which are described in more detail below.</p><p>The <strong>Project Diary</strong> module will not be covered in this section of the help.</p><p>In the <strong>Ticket Management</strong> module, only the <strong>Ticket List</strong> is available. This list applies only to the project shown in the menu header. If the user needs to access the ticket list of another project, they must first navigate to that project through the Project List.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>For <strong>quick switching between the diary and tickets</strong> of the current project, use the <strong>icons in the header of the diary or tickets</strong>:</p><p><img src="'+i+'" alt="Switch from Tickets to the Project Diary" width="250" loading="lazy"> <img src="'+o+'" alt="Switch from the Project Diary to Tickets" width="250" loading="lazy"></p></div><h2 id="project-list" tabindex="-1">Project List <a class="header-anchor" href="#project-list" aria-label="Permalink to &quot;Project List&quot;">​</a></h2><figure class="shot" style="--w:280px;"><img src="'+s+'" alt="Link to Project List" width="250" loading="lazy"></figure><p>The <strong>Project List</strong> is undoubtedly the primary icon in the navigation menu, allowing users to move freely from one project to another.</p><p>Its placement in the Main Menu provides quick access.</p><figure class="shot" style="--w:280px;"><img src="'+a+'" alt="Project List" width="250" loading="lazy"></figure><figure class="shot" style="--w:280px;"><img src="'+n+'" alt="Project Details" width="250" loading="lazy"></figure><p>The list displays all projects the user has access to.</p><p>The <strong>Details</strong> icon expands to show <strong>basic information about the project</strong>.</p><p>The <strong>Diary</strong> icon takes the user <strong>to the Project Diary</strong> of the project, or to the Diary List if the project has multiple diaries.</p><p>The <strong>Tickets</strong> icon takes the user <strong>to the Ticket List</strong> of the selected project.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>A module that is not activated for a project has an inactive (grayed-out) icon in the list.</p></div><p>The entire card containing the project image and name above the icons is also active ⇒ a project with one diary opens the diary&#39;s Daily Records for the current day / a project with multiple diaries opens the Diary List. If only Ticket Management is activated for the project and the Project Diary is not, the Ticket List page is opened.</p><h2 id="settings" tabindex="-1">Settings <a class="header-anchor" href="#settings" aria-label="Permalink to &quot;Settings&quot;">​</a></h2><figure class="shot" style="--w:280px;"><img src="'+r+'" alt="Link to Settings" width="250" loading="lazy"></figure><figure class="shot" style="--w:280px;"><img src="'+c+'" alt="Settings" width="250" loading="lazy"></figure><p>The <strong>Settings</strong> icon opens a page with a few configuration options:</p><ul><li><strong>Signature Settings</strong> → this is not relevant to the Ticket Management module. Signatures need to be configured for working with the Project Diary, so this functionality is described in the help section for the Project Diary module.</li><li><strong>Work Offline</strong> → users can switch to offline mode if they do not want to use mobile data. An internet connection is required to synchronize local data with the server, and users must manually switch back to online mode here.</li><li><strong>Feedback</strong> → do you have any comments about the app? Do you have an idea for how to improve it? You can submit your comments using the form available through this link.</li><li><strong>What&#39;s New</strong> → this opens the window that was displayed when you first entered the app but that you did not have time to read. If we have important information about new features or changes in the app, it will be shown when you log in, but you can also find it here at any time.</li><li><strong>Log Out</strong> → if you need to sign in with a different account, or simply want to log out before closing the app, you can do so here.</li></ul>',27)])])}const P=h(u,[["render",m]]);export{T as __pageData,P as default};
